                if genuine_period and any(ps[i]['vague_asked'] for i in active):
                    q['deadline'] = True
                    continue
                t['waiting'] = 'date'
                t['date_reason'] = 'period' if genuine_period else 'representation'
                if genuine_period:
                    for i in active:
