                text = 'What exact day do you mean for your ' + labels + '?' if genuine_period else 'Please give the exact payment day and month for your ' + labels + '.'
                emit('date', text, 'collection_question')
                return
            if any(datetime.date.fromisoformat(d) < today for i, a, mode, d in values):
                t['waiting'], t['date_reason'] = 'date', 'past'
                emit('date', 'That date is in the past. Please give today or a later business day, no later than ' + date_speech(min(ps[i]['deadline'] for i in active)) + '.', 'collection_question')
                return
            for i, a, mode, d in values:
                p = ps[i]
                if q['kind'] == 'too_much':
                    p['too_much'] = True
