                        reject(i, t['origin'])
                        continue
                    p['floor_offered'] = True
                if a < p['floor']:
                    if p['floor_offered']:
                        reject(i, t['origin'])
                        continue
                    prefix += 'I cannot record that amount. I can offer ' + money(p['floor']) + ' for your ' + p['label'] + '; the rest stays overdue. '
                    a = p['floor']
